#!/usr/bin/env node
// Generates every code copy of the country → location → AWS region → Atlas zone
// mapping from the single source of truth, shared/routing.json.
//
//   node scripts/sync-routing.mjs          rewrite the generated files
//   node scripts/sync-routing.mjs --check  exit 1 if any generated file is stale (CI)
//
// Generated (do not edit by hand):
//   backend/common/regions_data.py      region → locations and Atlas zones (every service)
//   backend/auth/countries_data.py      country → location, blocked countries (auth only)
//   backend/app/routing_data.py         today's backend; removed with it (build plan 8.6)
//   frontend/src/lib/countries.ts       frontend-app/src/lib/countries.ts
//   frontend/src/lib/locationHint.ts    frontend-app/src/lib/locationHint.ts
//
// Not generated — they read shared/routing.json directly at plan time:
//   infra-live-edge/terraform/routing.tf (Lambda@Edge routing, CloudFront
//   uploads routing, WAF geo-block). No dependencies: plain Node 18+.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = 'shared/routing.json';
const CHECK = process.argv.includes('--check');

const GENERATED_NOTE = `Generated by scripts/sync-routing.mjs from ${SOURCE} — do not edit.`;
const EDIT_NOTE = `Edit ${SOURCE}, then run \`node scripts/sync-routing.mjs\`.`;

// -- load + validate --------------------------------------------------------------

function fail(msg) {
  console.error(`${SOURCE}: ${msg}`);
  process.exit(1);
}

let data;
try {
  data = JSON.parse(fs.readFileSync(path.join(ROOT, SOURCE), 'utf8'));
} catch (err) {
  fail(`cannot read/parse: ${err.message}`);
}
const { regions, blocked_countries: blocked, countries } = data;
const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
if (!isObject(regions))
  fail('"regions" must be an object of AWS region → { atlas_zone, locations }');
if (!Array.isArray(blocked)) fail('"blocked_countries" must be an array of country codes');
if (!Array.isArray(countries)) fail('"countries" must be an array of { code, location, label }');

const LOCATION_RE = /^[a-z0-9_-]{1,16}$/; // same as LOCATION_RE in backend/common/regions.py
const CODE_RE = /^[A-Z]{2}$/;
const REGION_RE = /^[a-z]{2}-[a-z]+-\d$/;
const ZONE_RE = /^[A-Za-z0-9_]+$/;
// Labels are embedded in Python comments and TS string literals.
const LABEL_RE = /^[^"\\\n\r]+$/;

const locationToRegion = new Map();
const zones = new Set();
for (const [region, cfg] of Object.entries(regions)) {
  if (!isObject(cfg)) fail(`region ${region}: must be an object`);
  const { atlas_zone: zone, locations } = cfg;
  if (!REGION_RE.test(region)) fail(`invalid AWS region ${JSON.stringify(region)}`);
  if (!ZONE_RE.test(zone ?? '')) fail(`region ${region}: invalid atlas_zone`);
  if (zones.has(zone)) fail(`atlas_zone ${zone} used by more than one region`);
  zones.add(zone);
  if (!Array.isArray(locations) || locations.length === 0) fail(`region ${region}: no locations`);
  for (const loc of locations) {
    if (!LOCATION_RE.test(loc)) fail(`region ${region}: invalid location ${JSON.stringify(loc)}`);
    if (locationToRegion.has(loc)) fail(`location ${loc} assigned to two regions`);
    locationToRegion.set(loc, region);
  }
}

const blockedSet = new Set();
for (const code of blocked) {
  if (!CODE_RE.test(code)) fail(`invalid blocked country code ${JSON.stringify(code)}`);
  if (blockedSet.has(code)) fail(`blocked country ${code} listed twice`);
  blockedSet.add(code);
}

const seen = new Set();
for (const entry of countries) {
  if (!isObject(entry))
    fail(`countries: every entry must be an object, got ${JSON.stringify(entry)}`);
  const { code, location, label } = entry;
  if (!CODE_RE.test(code ?? '')) fail(`invalid country code ${JSON.stringify(code)}`);
  if (seen.has(code)) fail(`country ${code} listed twice`);
  seen.add(code);
  if (blockedSet.has(code)) fail(`country ${code} is both mapped and blocked`);
  if (!locationToRegion.has(location)) {
    fail(`country ${code}: location ${JSON.stringify(location)} is not in any region`);
  }
  if (!LABEL_RE.test(label ?? '')) fail(`country ${code}: invalid label ${JSON.stringify(label)}`);
}
for (const loc of locationToRegion.keys()) {
  if (!countries.some((c) => c.location === loc)) fail(`location ${loc} has no countries`);
}

const byCode = [...countries].sort((a, b) => (a.code < b.code ? -1 : 1));
const byLabel = [...countries].sort((a, b) => a.label.localeCompare(b.label, 'en'));

// -- renderers ----------------------------------------------------------------------

const tsString = (s) => (s.includes("'") ? `"${s}"` : `'${s}'`);

// Python blocks, shared by the files below. Formatted to match ruff format
// (line-length 100): one line if it fits, else wrapped.
function pyHeader() {
  return [`# ${GENERATED_NOTE}`, `# ${EDIT_NOTE}`, '# Grouping rules and their reasoning: shared/README.md.'];
}

function pyCountries() {
  return [
    '# Country (ISO-3166-1 alpha-2, plus XK) → location stored on the account and in its JWT.',
    'COUNTRY_TO_REGION: dict[str, str] = {',
    ...byCode.map((c) => `    "${c.code}": "${c.location}",  # ${c.label}`),
    '}',
  ];
}

function pyBlocked() {
  const blockedSetLiteral = `{${[...blockedSet]
    .sort()
    .map((c) => `"${c}"`)
    .join(', ')}}`;
  const blockedOneLine = `BLOCKED_COUNTRIES: frozenset[str] = frozenset(${blockedSetLiteral})`;
  return [
    '# Never served: refused at registration (403 country_not_supported) and geo-blocked by the WAF.',
    ...(blockedOneLine.length <= 100
      ? [blockedOneLine]
      : ['BLOCKED_COUNTRIES: frozenset[str] = frozenset(', `    ${blockedSetLiteral}`, ')']),
  ];
}

function pyRegions() {
  return [
    '# AWS region → locations its backend and worker serve (Lambda@Edge routes by the inverse).',
    'REGION_TO_LOCATIONS: dict[str, list[str]] = {',
    ...Object.entries(regions).map(
      ([r, v]) => `    "${r}": [${v.locations.map((l) => `"${l}"`).join(', ')}],`,
    ),
    '}',
  ];
}

function pyZones() {
  return [
    '# AWS region → Atlas Global Cluster zone holding its locations (backend/tools/atlas_zone_ranges.py).',
    'ATLAS_ZONE_FOR_REGION: dict[str, str] = {',
    ...Object.entries(regions).map(([r, v]) => `    "${r}": "${v.atlas_zone}",`),
    '}',
  ];
}

const pyFile = (...blocks) =>
  [...pyHeader(), ...blocks.flatMap((b) => ['', ...b])].join('\n') + '\n';

// Today's backend (backend/app); removed with it in build plan 8.6.
function renderPython() {
  return pyFile(pyCountries(), pyBlocked(), pyRegions(), pyZones());
}

// Every service: region scoping for workers and relays (docs/auth-users-split.md, 4.1).
function renderCommonRegions() {
  return pyFile(pyRegions(), pyZones());
}

// auth only: registration resolves a location from the country (section 16).
function renderAuthCountries() {
  return pyFile(pyCountries(), pyBlocked());
}

function renderCountries() {
  const lines = [
    `// ${GENERATED_NOTE}`,
    `// ${EDIT_NOTE}`,
    '//',
    '// ISO-3166-1 alpha-2 codes (plus XK, Kosovo) for every country/territory a user',
    '// can register from. Blocked countries are deliberately absent (never served).',
    'export const COUNTRIES = [',
    ...byLabel.map((c) => `  { code: '${c.code}', label: ${tsString(c.label)} },`),
    '].sort((a, b) => a.label.localeCompare(b.label));',
  ];
  return lines.join('\n') + '\n';
}

function renderLocationHint() {
  const lines = [
    `// ${GENERATED_NOTE}`,
    `// ${EDIT_NOTE}`,
    '',
    '/**',
    ' * Location per country, used only to compute the X-Client-Location header sent',
    " * on registration (see api/client.ts's `register` call). This is NEVER",
    " * authoritative — the account's real `location` field is always computed",
    " * server-side from the validated country_code, on whichever region's backend",
    " * actually receives the request (see Lambda@Edge's jwt-validator-lambda.js.tpl",
    ' * for how the header is consumed). A wrong hint only costs latency (the',
    ' * registration call lands on a sub-optimal region), never incorrect data.',
    ' */',
    'const COUNTRY_TO_LOCATION_HINT: Record<string, string> = {',
    ...byCode.map((c) => `  ${c.code}: '${c.location}',`),
    '};',
    '',
    '/**',
    ' * Returns a best-effort location hint for the given country code, or',
    ' * `undefined` if unrecognised. Deliberately does NOT fall back to a default',
    " * location the way the backend's resolve_region() does — sending no header",
    ' * at all is safer than a wrong guess, since the Lambda@Edge treats a missing',
    ' * hint as "use the bootstrap region" (always reachable) rather than risking',
    " * a guess that resolves to a region that isn't deployed.",
    ' */',
    'export function locationHint(countryCode: string): string | undefined {',
    '  return COUNTRY_TO_LOCATION_HINT[countryCode.trim().toUpperCase()];',
    '}',
  ];
  return lines.join('\n') + '\n';
}

// -- write / check ------------------------------------------------------------------

const outputs = {
  'backend/common/regions_data.py': renderCommonRegions(),
  'backend/auth/countries_data.py': renderAuthCountries(),
  'backend/app/routing_data.py': renderPython(),
  'frontend/src/lib/countries.ts': renderCountries(),
  'frontend-app/src/lib/countries.ts': renderCountries(),
  'frontend/src/lib/locationHint.ts': renderLocationHint(),
  'frontend-app/src/lib/locationHint.ts': renderLocationHint(),
};

// Compares (and, unless --check, rewrites) one generated file. Reads and writes
// go through a single file descriptor rather than separate path-based calls,
// so the file can't be swapped between the check and the write (CWE-367 /
// CodeQL js/file-system-race). Returns true if the file was stale.
function syncFile(file, content) {
  let fd;
  try {
    fd = fs.openSync(file, CHECK ? 'r' : fs.constants.O_RDWR | fs.constants.O_CREAT);
  } catch (err) {
    if (CHECK && err.code === 'ENOENT') return true; // missing counts as stale
    throw err;
  }
  try {
    if (fs.readFileSync(fd, 'utf8') === content) return false;
    if (!CHECK) {
      fs.ftruncateSync(fd, 0);
      fs.writeSync(fd, content, 0, 'utf8');
    }
    return true;
  } finally {
    fs.closeSync(fd);
  }
}

const stale = [];
for (const [rel, content] of Object.entries(outputs)) {
  if (syncFile(path.join(ROOT, rel), content)) stale.push(rel);
}

if (CHECK && stale.length) {
  console.error(
    `Stale generated files (run \`node scripts/sync-routing.mjs\`):\n  ${stale.join('\n  ')}`,
  );
  process.exit(1);
}
console.log(
  stale.length
    ? `${CHECK ? 'Stale' : 'Updated'}: ${stale.join(', ')}`
    : `All generated routing files are up to date (${countries.length} countries).`,
);
